class AurenReminderScreen extends StatefulWidget{const AurenReminderScreen({super.key});@override State<AurenReminderScreen> createState()=>_S();}
class _S extends State<AurenReminderScreen>{final t=TextEditingController(),n=TextEditingController();final s=ReminderService();@override void dispose(){t.dispose();n.dispose();super.dispose();}@override Widget build(BuildContext c){final u=FirebaseAuth.instance.currentUser?.uid;if(u==null)return const Scaffold(body:Center(child:Text('يجب تسجيل الدخول')));return Scaffold(appBar:AppBar(title:const Text('Reminders')),body:StreamBuilder(stream:s.watch(u),builder:(c,x){final a=x.data?.docs??[];return ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:t,decoration:const InputDecoration(labelText:'التذكير',prefixIcon:Icon(Icons.notifications_none))),TextField(controller:n,decoration:const InputDecoration(labelText:'ملاحظة')),const SizedBox(height:8),FilledButton.icon(onPressed:()async{if(t.text.trim().isNotEmpty){await s.create(u,t.text,n.text,DateTime.now().toUtc().toIso8601String());t.clear();n.clear();}},icon:const Icon(Icons.add_alert),label:const Text('إضافة')),const SizedBox(height:12),...a.map((d){final r=AurenReminder.fromMap(d.id,d.data());return Card(child:CheckboxListTile(value:r.done,onChanged:(_)=>s.done(u,r),title:Text(r.title),subtitle:Text(r.note.isEmpty?'بدون ملاحظة':r.note),secondary:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>s.delete(u,r.id)));})]);}));}}